383	// CancelSubscription 为当前有效订阅登记按月取消。
384	//
385	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
386	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
387	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
388	// 不把期限后移（Cancelled 为 false）。
389	//
390	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
391	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
392	//
393	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
394	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
395		if accountID == "" {
396			return CancelSubscriptionResult{}, invalidf("account id is empty")
397		}
398		s.mu.Lock()
399		defer s.mu.Unlock()
400	
401		acc, ok := s.accounts[accountID]
402		if !ok {
403			return CancelSubscriptionResult{}, ErrAccountNotFound
404		}
405		now := s.nowUTC()
406		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
407		s.settleLocked(acc, now)
408		if acc.sub == nil {
409			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
410		}
411		if now.Before(acc.sub.activatedAt) {
412			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
413		}
414	
415		// 重复取消：原样返回原终止时刻，不后移期限。
416		if acc.sub.cancelEnd != nil {
417			return CancelSubscriptionResult{
418				Cancelled:    false,
419				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
420			}, nil
421		}
422	
423		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
424		acc.sub.pending = nil
425		end := nextMonth(MonthOf(now)).Start()
426		acc.sub.cancelEnd = &end
427		return CancelSubscriptionResult{
428			Cancelled:    true,
429			Cancellation: SubscriptionCancellation{EndAt: end},
430		}, nil
431	}
432	
433	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
434	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
435	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
436	// 账户不存在或从未开通时同样失败。
437	func (s *Service) UndoCancelSubscription(accountID string) error {
438		if accountID == "" {
439			return invalidf("account id is empty")
440		}
441		s.mu.Lock()
442		defer s.mu.Unlock()
443		acc, ok := s.accounts[accountID]
444		if !ok {
445			return ErrAccountNotFound
446		}
447		// 到达终止时刻后订阅已终止：撤回失败。
448		s.settleLocked(acc, s.nowUTC())
449		if acc.sub == nil {
450			return ErrSubscriptionNotFound
451		}
452		acc.sub.cancelEnd = nil
453		return nil
454	}
