533	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
534	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
535	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
536	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
537	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
538	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
539		if accountID == "" {
540			return Bill{}, invalidf("account id is empty")
541		}
542		if period.Month < time.January || period.Month > time.December {
543			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
544		}
545		s.mu.Lock()
546		defer s.mu.Unlock()
547	
548		acc, ok := s.accounts[accountID]
549		if !ok {
550			return Bill{}, ErrAccountNotFound
551		}
552		if existing, ok := acc.bills[period]; ok {
553			return existing.bill, nil
554		}
555	
556		now := s.nowUTC()
557		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
558		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
559		// 也不会被后来的订阅覆盖。
560		s.settleLocked(acc, now)
561	
562		if acc.sub == nil && len(acc.history) == 0 {
563			return Bill{}, ErrSubscriptionNotFound
564		}
565		if period.End().After(now) {
566			return Bill{}, ErrBillMonthNotEnded
567		}
568	
569		sub := segmentForBillingLocked(acc, period)
570		if sub == nil {
571			// 早于首段开通，或处于两段订阅之间的空档。
572			return Bill{}, ErrBillBeforeSubscription
573		}
574	
575		terms := termsForPeriod(sub, period)
576		bill, err := buildBill(accountID, period, terms, acc.usage[period])
577		if err != nil {
578			return Bill{}, err
579		}
580		acc.bills[period] = &billRecord{bill: bill}
581		return bill, nil
582	}
583	
584	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
585	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
586		if accountID == "" {
587			return Bill{}, invalidf("account id is empty")
588		}
589		s.mu.Lock()
590		defer s.mu.Unlock()
591		acc, ok := s.accounts[accountID]
592		if !ok {
593			return Bill{}, ErrAccountNotFound
594		}
595		rec, ok := acc.bills[period]
596		if !ok {
597			return Bill{}, ErrBillNotFound
598		}
599		return rec.bill, nil
600	}
