602	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
603	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
604	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
605	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
606	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
607	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
608	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
609	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
610	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
611		if accountID == "" {
612			return PaymentResult{}, invalidf("account id is empty")
613		}
614		if paymentID == "" {
615			return PaymentResult{}, invalidf("payment id is empty")
616		}
617		if amount <= 0 {
618			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
619		}
620		s.mu.Lock()
621		defer s.mu.Unlock()
622	
623		acc, ok := s.accounts[accountID]
624		if !ok {
625			return PaymentResult{}, ErrAccountNotFound
626		}
627		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
628		if prev, ok := acc.payments[paymentID]; ok {
629			if prev.period != period || prev.amount != amount {
630				return PaymentResult{}, ErrPaymentConflict
631			}
632			// 完全相同的重报仍成功，但不再次登记、不改变账单：
633			// 返回这笔付款首次成功登记完成时的余额与付清状态，
634			// 不受账单后续收款、当前余额或停用/恢复状态影响。
635			return PaymentResult{
636				Registered:  false,
637				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
638				BillBalance: prev.balance,
639				Settled:     prev.settled,
640			}, nil
641		}
642	
643		rec, ok := acc.bills[period]
644		if !ok {
645			return PaymentResult{}, ErrBillNotFound
646		}
647	
648		if amount > rec.bill.Balance {
649			return PaymentResult{}, ErrPaymentExceedsBalance
650		}
651	
652		paid, ok := addNonNeg(rec.bill.Paid, amount)
653		if !ok {
654			return PaymentResult{}, ErrOverflow
655		}
656		rec.bill.Paid = paid
657		rec.bill.Balance -= amount
658		if rec.bill.Balance == 0 {
659			rec.bill.Settled = true
660		}
661		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
662		acc.payments[paymentID] = paymentRecord{
663			period:  period,
664			amount:  amount,
665			balance: rec.bill.Balance,
666			settled: rec.bill.Settled,
667		}
668	
669		return PaymentResult{
670			Registered:  true,
671			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
672			BillBalance: rec.bill.Balance,
673			Settled:     rec.bill.Settled,
674		}, nil
675	}
